import tarfile
import os
import shutil

def backup(path):
    tar = tarfile.open("backup.tar", "w")
    for root, dirs, files in os.walk(path+"/"):
        for f in files:
            tar.add(os.path.join(root, f))
    tar.close()

def restore(path, tar_path):
    if os.path.exists(path):
        shutil.rmtree(path)

    tar = tarfile.open(tar_path, "r")
    tar.extractall(members=[tar.getmember(f) for f in tar.getmembers() if "/Documents/" in f.name ], path=path+"/..")
    tar.close()

if __name__ == "__main__":
